type a1b2LoseNextWrite struct { store.Store; db *sql.DB; netID atomic.Value; armed, fired atomic.Bool }
func (f *a1b2LoseNextWrite) Update(ctx context.Context, fn func(store.Tx) error) error {
  if id, _ := f.netID.Load().(string); id != "" && f.armed.Load() {
    var closed int64; var sha string
    if f.db.QueryRowContext(ctx, `SELECT closed_at, final_sha256 FROM network_closures WHERE network_id = ?`, id).Scan(&closed, &sha) == nil && closed != 0 && sha == "" {
      f.armed.Store(false); f.fired.Store(true)
      return errors.New("verifier-injected: write unit lost after closure commit") } }
  return f.Store.Update(ctx, fn)
}
func TestVerifyA1b2_07_FinalExportNotRetried(t *testing.T) {
  var lw *a1b2LoseNextWrite
  e := tu.NewEnvWith(t, func(s store.Store) store.Store { lw = &a1b2LoseNextWrite{Store: s, db: s.(*store.SQLite).DB()}; return lw })
  w := &world{Env: e}; w.admin = e.Person("admin@example.org")
  w.net, w.adminM = e.Network(w.admin, "demo", nil)
  w.a, w.aM = e.Member(w.admin, w.net, "ana@example.org"); w.b, w.bM = e.Member(w.admin, w.net, "ben@example.org")
  w.Trade(w.net.ID, w.a, w.b, w.aM, w.bM, 500)
  tu.Must(w.schedule("end", 0)); w.Clock.Advance(31 * 24 * time.Hour)
  lw.netID.Store(w.net.ID); lw.armed.Store(true)
  n1, err1 := w.Svc.FinaliseClosures(w.Ctx, sysJob)
  c1 := w.netNow().Closure
  t.Logf("run 1: finalised=%d err=%v status=%s closed=%v sha=%q", n1, err1, w.netNow().Status, c1.Done(), c1.FinalSHA256)
  for i := 2; i <= 3; i++ { w.Clock.Advance(time.Hour); n, err := w.Svc.FinaliseClosures(w.Ctx, sysJob); t.Logf("run %d: %d %v %q", i, n, err, w.netNow().Closure.FinalSHA256) }
  _, verr := w.Svc.VerifyClosureExport(w.Ctx, w.admin, w.net.ID); t.Logf("verify: %v", verr)
  if w.netNow().Closure.FinalSHA256 == "" { t.Errorf("A1-07 REPRODUCED: no final export checksum after later runs") }
}

