//go:build verifyb1
// go test -tags verifyb1 -count=1 -run TestVB1_A101 -v ./internal/service/
package service_test

func settle(p *domain.Policy) { p.DepartureRule = domain.DepartSettleToZero }
func vb1Seq(t *testing.T, w *world) (s int64) {
  if err := w.Store.DB().QueryRow(`SELECT ledger_seq FROM networks WHERE id = ?`, w.net.ID).Scan(&s); err != nil { t.Fatal(err) }
  return s
}

func TestVB1_A101_Closed(t *testing.T) {
  w := newWorld(t, settle)
  w.Trade(w.net.ID, w.b, w.a, w.bM, w.aM, 700) // b=-700 a=+700
  tu.Must(w.schedule("pilot over", 0))
  w.Clock.Advance(30*24*time.Hour + time.Minute)
  if n := tu.Must(w.Svc.FinaliseClosures(w.Ctx, sysJob)); n != 1 || w.netNow().Status != domain.NetworkClosed { t.Fatal("precondition") }
  if !tu.Must(w.Svc.VerifyClosureExport(w.Ctx, w.admin, w.net.ID)).Match { t.Fatal("precondition") }
  _, aerr := w.adjust(w.admin, w.bM, 1, service.AdjustCredit, "x")
  wantCode(t, aerr, domain.ErrInvalidState) // control: adjustments refused on closure
  seq0 := vb1Seq(t, w)
  if _, err := w.Svc.DepartMember(w.Ctx, w.b, w.net.ID, service.DepartInput{}); err != nil { t.Fatalf("NOT REPRODUCED: %v", err) }
  if _, err := w.Svc.DepartMember(w.Ctx, w.admin, w.net.ID, service.DepartInput{MemberID: w.aM.ID, Reason: "cleanup"}); err != nil { t.Fatalf("NOT REPRODUCED: %v", err) }
  chk := tu.Must(w.Svc.VerifyClosureExport(w.Ctx, w.admin, w.net.ID))
  if vb1Seq(t, w) != seq0+2 || chk.Match { t.Fatal("NOT REPRODUCED") }
}

func TestVB1_A101_Closing(t *testing.T) {
  w := newWorld(t, settle)
  c, cM := w.Member2(w.admin, "carol@example.org")
  t1 := w.Trade(w.net.ID, w.a, w.b, w.aM, w.bM, 500)
  w.Trade(w.net.ID, c, w.b, cM, w.bM, 300) // c=-300
  tu.Must(w.schedule("end", 0))
  tu.Must(w.open(w.a, t1.ID)) // keeps the network closing after the date
  w.Clock.Advance(31 * 24 * time.Hour)
  if n := tu.Must(w.Svc.FinaliseClosures(w.Ctx, sysJob)); n != 0 || w.netNow().Status != domain.NetworkClosing { t.Fatal("precondition") }
  seq0 := vb1Seq(t, w)
  if _, err := w.Svc.DepartMember(w.Ctx, c, w.net.ID, service.DepartInput{}); err != nil || vb1Seq(t, w) == seq0 { t.Fatalf("NOT REPRODUCED: %v", err) }
}

func TestVB1_A101_Suspended(t *testing.T) {
  w := newWorld(t, settle)
  w.Trade(w.net.ID, w.a, w.b, w.aM, w.bM, 400)
  noErr(t, w.Svc.SuspendNetwork(w.Ctx, w.admin, w.net.ID, "security review"))
  _, perr := w.propose(w.b, w.aM, service.ProposerPays, 1)
  wantCode(t, perr, domain.ErrInvalidState) // control
  seq0 := vb1Seq(t, w)
  if _, err := w.Svc.DepartMember(w.Ctx, w.a, w.net.ID, service.DepartInput{}); err != nil || vb1Seq(t, w) == seq0 { t.Fatalf("NOT REPRODUCED: %v", err) }
}
// Also run: platform suspension; admin-required via the raw SQL of TestAdminRequiredReadOnly;
// API (package api_test): POST /api/v1/me/membership/departure on a closed network -> 200 "settled", checksum mismatch.

