//go:build verifyb1
// go test -tags verifyb1 -count=1 -run TestVB1_A102 -v ./internal/service/
package service_test

func TestVB1_A102_ScheduledDecimals(t *testing.T) {
  w := newWorld(t, nil)
  if w.net.Policy.Decimals != 2 || vb1Seq(t, w) != 0 { t.Fatal("precondition: decimals 2, no posting") }
  // Bundled with an adverse change, the default 14-day notice applies with no explicit notice_days.
  n, err := w.setPolicy(func(p *domain.Policy) { p.Decimals = 0; p.DefaultCreditLimit = 5000 }, nil, "")
  if err != nil { t.Fatalf("NOT REPRODUCED: scheduling refused: %v", err) }
  if n.Policy.Decimals != 2 { t.Fatal("precondition: scheduled, not yet in force") }
  w.Trade(w.net.ID, w.a, w.b, w.aM, w.bM, 2500) // 25.00
  _, cerr := w.setPolicy(func(p *domain.Policy) { p.Decimals = 3 }, iptr(0), "")
  wantCode(t, cerr, domain.ErrValidation) // control: immediate change now refused by the guard
  w.Clock.Advance(14*24*time.Hour + time.Minute)
  after := w.netNow()
  bal := w.balance(w.b).Balance
  t.Logf("decimals %d seq %d; %d minor reads %q (was %q)", after.Policy.Decimals, after.LedgerSeq, bal,
    domain.FormatAmount(bal, after.Policy.Decimals), domain.FormatAmount(bal, 2))
  if after.Policy.Decimals != 0 || after.LedgerSeq == 0 { t.Fatal("NOT REPRODUCED") }
  _, berr := w.setPolicy(func(p *domain.Policy) { p.Decimals = 2 }, iptr(0), "")
  wantCode(t, berr, domain.ErrValidation) // no way back
}
// API variant (package api_test): GET /admin/policy for the ETag; PATCH /api/v1/admin/policy
// {"decimals":0,"notice_days":14,"reason":"whole credits"} with If-Match -> 200; trade 2500; advance 15 days;
// GET /api/v1/accounts/me -> balance_minor "2500", decimals 0, ledger_seq 1.

