//go:build verifyb1
// go test -tags verifyb1 -count=1 -run TestVB1_A104 -v ./internal/service/
package service_test

func TestVB1_A104_AdminRequiredReversals(t *testing.T) {
  w := newWorld(t, nil)
  rev, _ := w.reviewerAs("rev1@example.org")
  rev2, _ := w.reviewerAs("rev2@example.org")
  c, cM := w.Member2(w.admin, "carol@example.org")
  t1 := w.Trade(w.net.ID, w.a, w.b, w.aM, w.bM, 600)
  d1 := tu.Must(w.open(w.a, t1.ID))
  t2 := w.Trade(w.net.ID, w.a, c, w.aM, cM, 300)
  w.Trade(w.net.ID, c, w.b, cM, w.bM, 10300) // c = -10000
  d2 := tu.Must(w.open(w.a, t2.ID))
  if g := tu.Must(w.resolve(rev, d2.ID, domain.OutcomeUpheld, 0, "upheld")); g.Status != domain.DisputePostingPending { t.Fatal("precondition") }
  lim := int64(1_000_000)
  noErr(t, w.Svc.SetCreditLimit(w.Ctx, w.admin, w.net.ID, service.SetLimitInput{MemberID: cM.ID, Limit: &lim, Reason: "room"}))
  t3 := w.Trade(w.net.ID, w.b, w.a, w.bM, w.aM, 100)
  d3 := tu.Must(w.open(w.b, t3.ID))
  tu.Must(w.resolve(rev, d3.ID, domain.OutcomeDismissed, 0, "no"))
  noErr(t, w.rereview(w.b, d3.ID, "again"))
  // administrator required: same raw-SQL technique as TestAdminRequiredReadOnly
  if _, err := w.Store.DB().Exec(`UPDATE members SET status='suspended' WHERE id = ?`, w.adminM.ID); err != nil { t.Fatal(err) }
  if !tu.Must(w.Svc.GetNetwork(w.Ctx, w.a, w.net.ID)).AdminRequired { t.Fatal("precondition") }
  _, perr := w.propose(w.a, w.bM, service.ProposerPays, 1)
  wantCode(t, perr, domain.ErrInvalidState) // control
  wantCode(t, w.decideRR(rev2, d3.ID, string(domain.OutcomeUpheld), 0), domain.ErrInvalidState) // control: re-review is gated
  seq0 := vb1Seq(t, w)
  if _, err := w.resolve(rev, d1.ID, domain.OutcomeUpheld, 0, "not delivered"); err != nil { t.Fatalf("NOT REPRODUCED: %v", err) }
  seq1 := vb1Seq(t, w)
  if _, err := w.Svc.RetryDisputePosting(w.Ctx, rev, w.net.ID, d2.ID); err != nil { t.Fatalf("NOT REPRODUCED: %v", err) }
  if seq1 == seq0 || vb1Seq(t, w) == seq1 { t.Fatal("NOT REPRODUCED") }
}

