func b3Rev(t *testing.T, w *world, origID string) string {
	var id string
	tu.Must(0, w.Store.DB().QueryRow(`SELECT id FROM transactions WHERE original_tx_id = ? AND kind = 'reversal'`, origID).Scan(&id))
	return id
}

// audit events an admin finds with the FR-084 target filter, and audit rows naming id anywhere
func b3Linkage(t *testing.T, w *world, id string) (byFilter, anywhere int) {
	byFilter = len(tu.Must(w.Svc.ListAudit(w.Ctx, w.admin, w.net.ID, service.AuditQuery{TargetID: id})))
	tu.Must(0, w.Store.DB().QueryRow(`SELECT COUNT(*) FROM audit_events WHERE target_id = ? OR
		instr(summary_before || summary_after || reason, ?) > 0`, id, id).Scan(&anywhere))
	return
}

func TestB3_A109_DisputeReversalAuditLinkage(t *testing.T) {
	check := func(t *testing.T, w *world, revID string, want int) {
		f, a := b3Linkage(t, w, revID)
		t.Logf("reversal %s: by target filter=%d, anywhere=%d", revID, f, a)
		if f != want || a != want {
			t.Fatalf("want %d/%d, got %d/%d", want, want, f, a)
		}
	}
	t.Run("control_admin_reversal", func(t *testing.T) {
		w := newWorld(t, nil)
		tx := w.Trade(w.net.ID, w.a, w.b, w.aM, w.bM, 1000)
		check(t, w, tu.Must(w.reverse(w.admin, tx.ID, 300, "typo")).ID, 1)
	})
	t.Run("resolve_upheld", func(t *testing.T) {
		w := newWorld(t, nil)
		r1, _ := w.reviewerAs("r1@example.org")
		tx := w.Trade(w.net.ID, w.a, w.b, w.aM, w.bM, 400)
		d := tu.Must(w.open(w.a, tx.ID))
		tu.Must(w.resolve(r1, d.ID, domain.OutcomeUpheld, 0, "not delivered"))
		ev := tu.Must(w.Svc.ListAudit(w.Ctx, w.admin, w.net.ID, service.AuditQuery{TargetID: d.ID, Action: domain.ActDisputeResolved}))
		t.Logf("dispute.resolved after=%s", ev[0].SummaryAfter)
		check(t, w, b3Rev(t, w, tx.ID), 0)
	})
	t.Run("retry_after_posting_pending", func(t *testing.T) {
		w := newWorld(t, func(p *domain.Policy) { p.DefaultCreditLimit = 2500 })
		r1, _ := w.reviewerAs("r1@example.org")
		c, cM := w.Member2(w.admin, "carol@example.org")
		tx := w.Trade(w.net.ID, w.a, w.b, w.aM, w.bM, 2500)
		w.Trade(w.net.ID, w.b, c, w.bM, cM, 5000)
		d := tu.Must(w.open(w.a, tx.ID))
		if got := tu.Must(w.resolve(r1, d.ID, domain.OutcomeUpheld, 0, "x")); got.Status != domain.DisputePostingPending {
			t.Fatalf("setup: %s", got.Status)
		}
		big, exp := int64(10000), w.Clock.Now().Add(24*time.Hour)
		tu.Must(0, w.Svc.SetCreditLimit(w.Ctx, w.admin, w.net.ID, service.SetLimitInput{MemberID: w.bM.ID, Limit: &big, ExpiresAt: &exp, Reason: "override"}))
		tu.Must(w.Svc.RetryDisputePosting(w.Ctx, r1, w.net.ID, d.ID))
		check(t, w, b3Rev(t, w, tx.ID), 0)
	})
	t.Run("rereview_partial", func(t *testing.T) {
		w := newWorld(t, nil)
		r1, _ := w.reviewerAs("r1@example.org")
		r2, _ := w.reviewerAs("r2@example.org")
		tx := w.Trade(w.net.ID, w.a, w.b, w.aM, w.bM, 900)
		d := tu.Must(w.open(w.a, tx.ID))
		tu.Must(w.resolve(r1, d.ID, domain.OutcomeDismissed, 0, "no"))
		tu.Must(0, w.rereview(w.a, d.ID, "new evidence"))
		tu.Must(0, w.decideRR(r2, d.ID, "partially_upheld", 300))
		check(t, w, b3Rev(t, w, tx.ID), 0)
	})
}

