func TestVerifyB1_A201_CaseVariantKeys(t *testing.T) {
	w := newWorld(t)
	post := func(path, raw string) (int, map[string]any) {
		rec := w.do(req{method: "POST", path: path, token: w.aliceT, raw: raw,
			hdr: map[string]string{"Idempotency-Key": w.key()}})
		var body map[string]any
		if rec.Code < 300 {
			body = decode[map[string]any](t, rec)
		}
		t.Logf("%s %s -> %d %s", path, raw, rec.Code, rec.Body.String())
		return rec.Code, body
	}
	cp := `"counterparty_member_id":"` + w.bobM.ID + `","direction":"pay"`
	if code, _ := post("/api/v1/transactions", `{`+cp+`,"amount_minor":"100","amount_minor":"7"}`); code != 400 {
		t.Fatalf("control exact duplicate: %d", code)
	}
	if code, _ := post("/api/v1/transactions", `{`+cp+`,"amount_minorx":"7"}`); code != 400 {
		t.Fatalf("control unknown field: %d", code)
	}
	// API-003 + OpenAPI additionalProperties:false require 400 invalid-body here.
	code, body := post("/api/v1/transactions", `{`+cp+`,"amount_minor":"100","AMOUNT_MINOR":"7"}`)
	if code == 400 {
		t.Fatalf("not reproduced")
	}
	if code != 201 || body["amount_minor"] != "7" {
		t.Fatalf("unexpected: %d %v", code, body["amount_minor"])
	}
	code, body = post("/api/v1/transactions", `{`+cp+`,"AMOUNT_MINOR":"7","amount_minor":"100"}`)
	if code != 201 || body["amount_minor"] != "100" {
		t.Fatalf("reversed: %d %v", code, body["amount_minor"])
	}
	code, body = post("/api/v1/transactions",
		`{"Counterparty_Member_ID":"`+w.bobM.ID+`","DIRECTION":"pay","Amount_Minor":"9"}`)
	if code != 201 || body["amount_minor"] != "9" {
