	}
	if code, body = post("/api/v1/listings", `{"KIND":"offer","Title":"bike"}`); code != 201 {
		t.Fatalf("listing wrong case: %d %v", code, body)
	}
	code, body = post("/api/v1/transactions", `{`+cp+`,"amount_minor":"11","de`+"ſ"+`cription":"x"}`)
	t.Logf("long-s description -> %d %v", code, body["description"])
}

