func TestVerifyB1_A202_ScopedTokenPersonWide(t *testing.T) {
	w := newWorld(t)
	ctx := w.env.Ctx
	founder := w.env.Person("zfounder")
	net2, _ := w.env.Network(founder, "zeta", nil)
	inv, _ := testutil.Must2(w.env.Svc.CreateInvitation(ctx, founder, net2.ID, service.InviteInput{}))
	testutil.Must(w.env.Svc.RedeemInvitation(ctx, w.alice, inv, "alice-z"))
	rw := []domain.Scope{domain.ScopeRead, domain.ScopeWrite}
	acmeTok, _ := testutil.Must2(w.env.Svc.CreateAPIToken(ctx, w.alice, service.TokenInput{Name: "acme-bot", Scopes: rw, NetworkID: w.net.ID}))
	zetaTok, zetaRow := testutil.Must2(w.env.Svc.CreateAPIToken(ctx, w.alice, service.TokenInput{Name: "zeta-bot", Scopes: rw, NetworkID: net2.ID}))
	fullTok, fullRow := testutil.Must2(w.env.Svc.CreateAPIToken(ctx, w.alice, service.TokenInput{Name: "full", Scopes: rw}))
	// Controls: design confines the acme token to acme.
	if me := w.get(acmeTok, "/me"); me.Code != 200 || strings.Contains(me.Body.String(), net2.ID) {
		t.Fatalf("control /me: %d", me.Code)
	}
	wantStatus(t, w.do(req{method: "GET", path: "/api/v1/network", token: acmeTok, hdr: map[string]string{"X-Network": "zeta"}}), 404)
	list := w.get(acmeTok, "/tokens")
	if list.Code != 200 || !strings.Contains(list.Body.String(), net2.ID) || !strings.Contains(list.Body.String(), "zeta-bot") {
		t.Fatalf("not reproduced (list)")
	}
	d1 := w.do(req{method: "DELETE", path: "/api/v1/tokens/" + zetaRow.ID, token: acmeTok})
	d2 := w.do(req{method: "DELETE", path: "/api/v1/tokens/" + fullRow.ID, token: acmeTok})
	if d1.Code != 204 || d2.Code != 204 {
		t.Fatalf("not reproduced (revoke) %d %d", d1.Code, d2.Code)
