// package contract; uses the existing newHarness (doc, router, env).
func vCall(t *testing.T, h *harness, hd http.Handler, method, path, tok, body string) (int, error) {
	mk := func() *http.Request {
		r := httptest.NewRequest(method, path, bytes.NewReader([]byte(body)))
		if body != "" { r.Header.Set("Content-Type", "application/json; charset=utf-8") }
		r.Header.Set("Authorization", "Bearer "+tok)
		if method == http.MethodPost { r.Header.Set("Idempotency-Key", h.key()) }
		return r }
	rec := httptest.NewRecorder(); hd.ServeHTTP(rec, mk())
	vr := mk(); route, params, err := h.router.FindRoute(vr)
	if err != nil { t.Fatal(err) }
	noAuth := func(context.Context, *openapi3filter.AuthenticationInput) error { return nil }
	rin := &openapi3filter.RequestValidationInput{Request: vr, PathParams: params, Route: route, Options: &openapi3filter.Options{AuthenticationFunc: noAuth}}
	out := &openapi3filter.ResponseValidationInput{RequestValidationInput: rin, Status: rec.Code, Header: rec.Header(), Options: &openapi3filter.Options{IncludeResponseStatus: true}}
	out.SetBodyBytes(rec.Body.Bytes())
	return rec.Code, openapi3filter.ValidateResponse(context.Background(), out)
}
