func TestVerifyA2_21_TokenHashUnkeyedUnsalted(t *testing.T) {
	plain := func(s string) string { h := sha256.Sum256([]byte(s)); return hex.EncodeToString(h[:]) }
	for _, secret := range []string{"server-secret-one-0123456789abcdef", "a-completely-different-secret-XYZ"} {
		e := tu.NewEnvConfig(t, nil, func(c *service.Config) { c.SecretKey = []byte(secret) })
		actor := e.Person("ana@example.org")
		sess, _, err := e.Svc.Login(e.Ctx, "ana@example.org", "correct horse battery")
		if err != nil {
			t.Fatal(err)
		}
		apiTok, row, err := e.Svc.CreateAPIToken(e.Ctx, actor, service.TokenInput{Name: "ci", Scopes: []domain.Scope{domain.ScopeRead}})
		if err != nil {
			t.Fatal(err)
		}
		db := e.Store.DB()
		var storedTok, storedSess string
		var saltCols int
		if err := db.QueryRow(`SELECT token_hash FROM api_tokens WHERE id = ?`, row.ID).Scan(&storedTok); err != nil {
			t.Fatal(err)
		}
		if err := db.QueryRow(`SELECT id FROM sessions LIMIT 1`).Scan(&storedSess); err != nil {
			t.Fatal(err)
		}
		_ = db.QueryRow(`SELECT (SELECT COUNT(*) FROM pragma_table_info('api_tokens') WHERE name LIKE '%salt%' OR name LIKE '%key%')
			+ (SELECT COUNT(*) FROM pragma_table_info('sessions') WHERE name LIKE '%salt%' OR name LIKE '%key%')`).Scan(&saltCols)
		if storedTok != plain(apiTok) || storedSess != plain(sess) || saltCols != 0 {
			t.Errorf("hash is keyed or salted after all")
		}
		var n int // offline confirmation of a candidate token against a leaked hash list
		_ = db.QueryRow(`SELECT COUNT(*) FROM api_tokens WHERE token_hash = ?`, plain(apiTok)).Scan(&n)
		if n != 1 {
			t.Errorf("offline candidate check: %d", n)
		}
		// Severity bound: a leaked stored hash is not itself a usable credential.
		if _, err := e.Svc.Authenticate(e.Ctx, storedSess); err == nil {
			t.Errorf("stored session hash accepted as a session token")
		}
		if _, err := e.Svc.AuthenticateToken(e.Ctx, "cir_"+storedTok); err == nil {
			t.Errorf("stored token hash accepted as an API token")
		}
	}
}

