// VB1-F16: a stolen session alone keeps the owner out of MFA sign-in.
func TestVB1_F16_StolenSessionHoldsMFALock(t *testing.T) {
	e := tu.NewEnv(t)
	owner := e.Person("owner@example.org")
	secret, _ := enrol(t, e, owner)
	r := login(e, "owner@example.org") // owner signs in after enrolment; the attacker steals this session
	tok, _ := tu.Must2(e.Svc.CompleteMFA(e.Ctx, r.MFAChallenge, totpAt(t, secret, now(e))))
	stolen := tu.Must(e.Svc.Authenticate(e.Ctx, tok))
	e.Clock.Advance(31 * time.Second)
	for i := 0; i < 5; i++ { // no password, no code
		t.Logf("attacker DisableMFA #%d -> %v", i+1, e.Svc.DisableMFA(e.Ctx, stolen, "not-the-password", "000000"))
	}
	ownerTry := func() error {
		rr := login(e, "owner@example.org") // password step succeeds
		_, _, err := e.Svc.CompleteMFA(e.Ctx, rr.MFAChallenge, totpAt(t, secret, now(e)))
		return err
	}
	locked := 0
	if domain.CodeOf(ownerTry()) == domain.CodeRateLimited {
		locked++
	}
	const rounds = 8 // two hours
	for i := 0; i < rounds; i++ {
		e.Clock.Advance(15*time.Minute + time.Second)      // lock has run out
		_ = e.Svc.DisableMFA(e.Ctx, stolen, "x", "000000") // one call re-arms it
		if domain.CodeOf(ownerTry()) == domain.CodeRateLimited {
			locked++
		}
		e.Clock.Advance(31 * time.Second)
	}
	if _, err := e.Svc.Authenticate(e.Ctx, tok); err != nil {
		t.Fatalf("stolen session died: %v", err)
	}
	e.Clock.Advance(16 * time.Minute) // control: attacker stops, lock lapses
	if err := ownerTry(); err != nil {
		t.Fatalf("control: owner still refused: %v", err)
	}
	t.Logf("owner (correct password + TOTP) refused in %d of %d attempts", locked, rounds+1)
	if locked == rounds+1 {
		t.Errorf("REPRODUCED: one DisableMFA call per 15 min from a stolen session keeps the owner out")
	}
}

