	maria, _ := env.Member(admin, net, name) // display name = login
	testutil.Must(env.Svc.CreateListing(env.Ctx, maria, net.ID, service.ListingInput{Type: domain.ListingOffer,
		Title: title, Description: "synthetic", IdempotencyKey: env.Key()}))
	h := NewHandlerWithOptions(env.Svc, Options{Now: env.Clock.Now}).(*server)
	tok := func(a domain.Actor) string {
		raw, _ := testutil.Must2(env.Svc.CreateAPIToken(env.Ctx, a, service.TokenInput{Name: "t", Scopes: []domain.Scope{domain.ScopeRead, domain.ScopeWrite}}))
		return raw
	}
	call := func(method, path, tk, body string) *httptest.ResponseRecorder {
		r := httptest.NewRequest(method, path, strings.NewReader(body))
		r.Header.Set("Authorization", "Bearer "+tk)
		r.Header.Set("Content-Type", "application/json")
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, r)
		return rec
	}
