		if err != nil {
			t.Fatalf("zip: %d %v", rec.Code, err)
		}
		var b strings.Builder
		for _, f := range zr.File {
			rc, _ := f.Open()
			d, _ := io.ReadAll(rc)
			_ = rc.Close()
			b.Write(d)
		}
		return b.String()
	}
	mk := func(tk, scope string) (d exportDTO) {
		if rec := call("POST", "/api/v1/exports", tk, `{"scope":"`+scope+`","format":"json"}`); rec.Code != 201 || json.Unmarshal(rec.Body.Bytes(), &d) != nil {
			t.Fatalf("export: %d %s", rec.Code, rec.Body.String())
		}
		return d
