		t.Fatal("premise: live tables still hold the canary")
	}
	after := call("GET", *exA.ArtefactURL, adminT, "")
	if body := text(after); after.Code != 200 || !strings.Contains(body, name) || !strings.Contains(body, title) {
		t.Fatalf("not reproduced: %d", after.Code)
	}
	env.Clock.Advance(24*time.Hour + time.Millisecond) // the window is bounded by the 24 h artefact TTL
	if rec := call("GET", *exA.ArtefactURL, adminT, ""); rec.Code != 404 {
