func TestVerifyB5_MFALockDurationDoesNotDouble(t *testing.T) {
	e := tu.NewEnv(t)
	a := e.Person("vera@example.org")
	secret, _ := enrol(t, e, a)
	lockLeft := func() time.Duration {
		var until int64
		if err := e.Store.DB().QueryRow(`SELECT locked_until FROM login_throttle WHERE login = ?`, "\x1fmfa:"+a.PersonID).Scan(&until); err != nil {
			t.Fatal(err)
		}
		return time.UnixMilli(until).Sub(now(e))
	}
	r := login(e, "vera@example.org")
	for i := 0; i < 5; i++ {
		_, _, _ = e.Svc.CompleteMFA(e.Ctx, r.MFAChallenge, "000000")
	}
	seen := []time.Duration{lockLeft()}
	for cycle := 0; cycle < 6; cycle++ { // failures 6..11
		e.Clock.Advance(lockLeft() + time.Second)
		fresh := login(e, "vera@example.org") // challenges live 5 minutes
		if _, _, err := e.Svc.CompleteMFA(e.Ctx, fresh.MFAChallenge, "000000"); domain.CodeOf(err) != domain.CodeUnauthenticated {
			t.Fatalf("cycle %d: want a counted failure, got %v", cycle, err)
		}
		seen = append(seen, lockLeft())
	}
	for i, d := range seen {
		if d != 15*time.Minute {
			t.Errorf("failure %d: lock %v, not the flat 15m", i+5, d)
		}
	}
	e.Clock.Advance(15*time.Minute + time.Second) // documented doubling would be 16h by now
	if _, _, err := e.Svc.CompleteMFA(e.Ctx, login(e, "vera@example.org").MFAChallenge, totpAt(t, secret, now(e))); err != nil {
		t.Errorf("lock still holds at 15m01s after 11 failures: %v", err)
	}
}
